header {
  width: 100%;
  max-width: 560px;
  margin-bottom: 2.5rem;
  text-align: center;
}
header h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--color-text);
}
header p {
  margin-top: .5rem;
  color: var(--color-muted);
  font-size: .9375rem;
}

main {
  width: 100%;
  max-width: 560px;
}

/* ── Card ── */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: calc(var(--radius) * 2);
  box-shadow: var(--shadow-lg);
  padding: 2.5rem 2rem;
}

