.helper-text {
  font-size: .8125rem;
  color: var(--color-helper);
  line-height: 1.4;
}

.error-text {
  font-size: .8125rem;
  color: var(--color-error);
  font-weight: 500;
  line-height: 1.4;
  display: none;
}
.error-text.visible { display: block; }

