.btn-submit:hover  { background: var(--color-primary-h); }
.btn-submit:active { background: var(--color-primary-a); }
.btn-submit:focus-visible {
  outline: 3px solid transparent;
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgb(59 130 246 / .45);
}

/* ── Success banner ── */
.success-banner {
  display: none;
  background: #f0fdf4;
  border: 1.5px solid #86efac;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  color: #166534;
  font-weight: 500;
  font-size: .9375rem;
}
.success-banner.visible { display: block; }

/* ── Status live region ── */
#form-status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }

/* ── Reflow (320 px) ── */
@media (max-width: 400px) {
  .card { padding: 1.5rem 1rem; }
  header h1 { font-size: 1.5rem; }
}

