@media (forced-colors: active) {
  .form-field input:focus,
  .btn-submit:focus-visible {
    outline: 3px solid ButtonText;
    outline-offset: 2px;
    box-shadow: none;
  }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonBorder; }
  .btn-submit:hover { background: Highlight; color: HighlightText; }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; }
}
