  const FIELDS = [
    {
      id: "full-name",
      name: "fullName",
      label: "Full Name",
      type: "text",
      required: true,
      autocomplete: "name",
      placeholder: "Jane Smith",
      validate(value) {
        if (!value.trim()) return "Full name is required.";
        if (value.trim().length < 2) return "Please enter your full name.";
        return null;
      },
    },
    {
      id: "email-address",
      name: "email",
      label: "Email Address",
      type: "email",
      required: true,
      autocomplete: "email",
      placeholder: "jane@example.com",
      validate(value) {
        if (!value.trim()) return "Email address is required.";
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return "Enter a valid email address (e.g. jane@example.com).";
        return null;
      },
    },
    {
      id: "phone-number",
      name: "phone",
      label: "Phone Number",
      type: "tel",
      required: false,
      autocomplete: "tel",
      placeholder: "+1 (555) 000-0000",
      helperText: "Optional. Use international format: +1 (555) 000-0000",
      validate(value) {
        if (!value.trim()) return null; // optional
        if (!/^\+?[\d\s\(\)\-]{7,20}$/.test(value.trim()))
          return "Enter a valid phone number, e.g. +1 (555) 000-0000.";
        return null;
      },
